UPDATE note_block SET type = CASE id
WHEN #{block.id} THEN #{block.type}
END , order_key = CASE id
WHEN #{block.id} THEN #{block.orderKey}
END , delta_json = CASE id
WHEN #{block.id} THEN #{block.deltaJson}
END , version = CASE id
WHEN #{block.id} THEN version + 1
END, updated_at = CURRENT_TIMESTAMP WHERE
(id = #{block.id} AND version = #{block.version})
